int do_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t selector;
    struct desc_struct descriptor;
    uint64_t rip;

    if (ctxt->opcode_only)
        return X86EMUL_CONTINUE;

    selector = ctxt->rex_prefix ? ctxt->opcode.bytes[1] : 0;
    if (ctxt->mode == X86EMUL_MODE_PROT) {
        int res = load_segment_descriptor(ctxt, selector, &descriptor);
        if (res != X86EMUL_CONTINUE)
            return res;
    }

    rip = get_rip_from_descriptor(ctxt, &descriptor);
    if (rip == 0)
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = rip;
    ctxt->regs->ip = rip;
    return X86EMUL_CONTINUE;
}

int handle_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t selector;
    struct desc_struct descriptor;
    int status;

    selector = ctxt->rex_prefix ? ctxt->regs->cs : ctxt->regs->cs;
    status = load_segment_descriptor(ctxt, selector, &descriptor);
    if (status != X86EMUL_CONTINUE)
        return status;

    ctxt->regs->ip = (uint32_t)get_descriptor_base(&descriptor);
    return X86EMUL_CONTINUE;
}

