int handle_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t selector;
    struct desc_struct descriptor;
    int rc;

    rc = get_segment_selector(ctxt, &selector);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = get_segment_descriptor(ctxt, selector, &descriptor);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    rc = set_instruction_pointer(ctxt, descriptor.base);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    return X86EMUL_CONTINUE;
}

int do_far_jump(struct x86_emulate_ctxt *ctxt) {
    int rc;
    struct segment_descriptor *desc;
    unsigned short selector;

    rc = get_segment_selector(ctxt, &selector);
    if (rc != X86EMUL_CONTINUE)
        return rc;

    desc = get_segment_descriptor(selector);
    if (!desc)
        return X86EMUL_UNHANDLEABLE;

    ctxt->eip = get_offset_from_descriptor(desc);
    return X86EMUL_CONTINUE;
}
